import { useState } from "react";
import axios from "axios";
import sorsuLogo from "../assets/sorsu-logo.png";

const API_URL = "http://localhost:5000";

function AuthPage({ setAuth }) {

  const [showPassword, setShowPassword] = useState(false);

  const [form, setForm] = useState({
    email: "",
    password: "",
  });

  const [voterCode, setVoterCode] = useState("");

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // ADMIN LOGIN
  const handleAdminLogin = async (e) => {
    e.preventDefault();

    try {

      const { data } = await axios.post(
        `${API_URL}/api/auth/login`,
        form
      );

      localStorage.setItem("token", data.token);
      localStorage.setItem("role", data.role);

      setAuth(data);

    } catch (err) {
      alert(err.response?.data?.message || "Admin login failed");
    }
  };

  // VOTER CODE LOGIN
  const handleVoterLogin = async () => {

    if (!voterCode) {
      alert("Please enter voter code");
      return;
    }

    try {

      const { data } = await axios.post(
        `${API_URL}/api/auth/login-code`,
        { code: voterCode }
      );

      localStorage.setItem("token", data.token);
      localStorage.setItem("role", data.role);

      setAuth(data);

    } catch (err) {
      alert(err.response?.data?.message || "Invalid voter code");
    }

  };

  return (
    <div style={styles.container}>

      {/* LEFT SIDE */}
      <div style={styles.left}>
        <div style={styles.logoRow}>
          <img src={sorsuLogo} alt="SorSU Logo" style={styles.logo} />

          <div>
            <h1 style={{ margin: 0 }}>Election 2026</h1>
            <h3 style={{ margin: 0, fontWeight: "normal" }}>
              Online Voting System
            </h3>
          </div>
        </div>
      </div>

      {/* RIGHT SIDE */}
      <div style={styles.right}>
        <div style={styles.card}>

          <h2 style={{ textAlign: "center" }}>Login Portal</h2>

          {/* VOTER LOGIN */}
          <div style={{ marginBottom: 25 }}>
            <h3 style={{ marginBottom: 10 }}>Voter Login</h3>

            <input
              type="text"
              placeholder="Enter Voter Code"
              value={voterCode}
              onChange={(e) => setVoterCode(e.target.value)}
              style={styles.input}
            />

            <button
              onClick={handleVoterLogin}
              style={styles.button}
            >
              Enter Voting Portal
            </button>
          </div>

          <hr style={{ margin: "20px 0", opacity: 0.2 }} />

          {/* ADMIN LOGIN */}
          <form onSubmit={handleAdminLogin}>

            <h3 style={{ marginBottom: 10 }}>Admin Login</h3>

            <input
              type="email"
              name="email"
              placeholder="Admin Email"
              onChange={handleChange}
              required
              style={styles.input}
            />

            <div style={{ position: "relative" }}>
              <input
                type={showPassword ? "text" : "password"}
                name="password"
                placeholder="Password"
                onChange={handleChange}
                required
                style={styles.input}
              />

              <span
                onClick={() => setShowPassword(!showPassword)}
                style={styles.eye}
              >
                👁
              </span>
            </div>

            <button type="submit" style={styles.button}>
              Admin Login
            </button>

          </form>

        </div>
      </div>

    </div>
  );
}

const styles = {
  container: {
    position: "fixed",
    inset: 0,
    display: "flex",
    background: "linear-gradient(135deg, #8B0000, #B22222)",
    fontFamily: "Arial",
  },

  left: {
    flex: 1,
    color: "white",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },

  logoRow: {
    display: "flex",
    alignItems: "center",
    gap: 20,
  },

  logo: {
    width: 110,
  },

  right: {
    flex: 1,
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },

  card: {
    backgroundColor: "#1c1c1c",
    padding: 40,
    borderRadius: 12,
    width: 380,
    color: "white",
    boxShadow: "0 0 30px rgba(0,0,0,0.6)",
  },

  input: {
    width: "100%",
    padding: 10,
    marginBottom: 15,
    borderRadius: 6,
    border: "none",
    backgroundColor: "#2c2c2c",
    color: "white",
  },

  button: {
    width: "100%",
    padding: 12,
    backgroundColor: "#2563eb",
    border: "none",
    borderRadius: 6,
    color: "white",
    fontWeight: "bold",
    cursor: "pointer",
  },

  eye: {
    position: "absolute",
    right: 10,
    top: 10,
    cursor: "pointer",
  },
};

export default AuthPage;
